package com.ejemplo.tienda.pedidos.internal;
import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/pedidos") class OrderController { private final OrderService service; OrderController(OrderService service){this.service=service;} record Request(String clienteId,long productoId,int cantidad){} @PostMapping @ResponseStatus(HttpStatus.CREATED) Order create(@RequestBody Request r){return service.create(r.clienteId(),r.productoId(),r.cantidad());} @GetMapping("/{id}") Order find(@PathVariable long id){return service.find(id);} @GetMapping("/cliente/{cliente}") long total(@PathVariable String cliente){return service.totalCliente(cliente);} @ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) String error(IllegalArgumentException e){return e.getMessage();} }
